import requests

def download_pwt_csv():
    url = "https://raw.githubusercontent.com/jivizcaino/PWT10.1/main/pwt101.csv"
    try:
        r = requests.get(url)
        r.raise_for_status()
        with open('pwt101.csv', 'wb') as f:
            f.write(r.content)
        print("PWT CSV downloaded.")
    except Exception as e:
        print(f"Error downloading PWT CSV: {e}")

if __name__ == "__main__":
    download_pwt_csv()

