import pandas as pd

def process_pwt():
    try:
        df = pd.read_csv('pwt101.csv', encoding='latin1')
        geo = df[df['countrycode'] == 'GEO']
        # Columns: year, rnna (Capital), emp (Labor), labsh (Labor share), delta, xr (Exchange Rate), rgdpna (Real GDP)
        geo = geo[['year', 'rnna', 'emp', 'labsh', 'delta', 'xr', 'rgdpna']]
        geo.to_csv('pwt_georgia.csv', index=False)
        print("PWT Georgia data saved.")
    except Exception as e:
        print(f"Error processing PWT: {e}")

if __name__ == "__main__":
    process_pwt()

